{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://gantry.invalid/protocol/activity-observation/v1/schema.json",
  "title": "Gantry nondurable activity observation vectors v1",
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "format": { "const": "gantry.activity-observation-vectors/v1" },
    "event_completion": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "kind": { "const": "parse" },
        "layer": { "const": "physical" },
        "activity_material": { "$ref": "#/$defs/material" },
        "event_material": { "$ref": "#/$defs/material" },
        "timestamp": { "$ref": "#/$defs/timestamp" }
      },
      "required": ["kind", "layer", "activity_material", "event_material", "timestamp"]
    },
    "projection_cases": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "class": {
            "enum": [
              "integration-diagnostic",
              "normalized-decision",
              "normalized-operation-error",
              "normalized-value",
              "operation-request",
              "raw-output",
              "source-snippet"
            ]
          },
          "raw_output": { "type": "boolean" },
          "operation_request_content": { "type": "boolean" },
          "operation_result_content": { "type": "boolean" },
          "integration_diagnostics": { "type": "boolean" },
          "source_snippets": { "type": "boolean" },
          "expected": { "enum": ["available", "redacted"] }
        },
        "required": [
          "class",
          "raw_output",
          "operation_request_content",
          "operation_result_content",
          "integration_diagnostics",
          "source_snippets",
          "expected"
        ]
      }
    },
    "retry_cases": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "initial_delay_us": { "$ref": "#/$defs/portableInteger" },
          "cap_us": { "$ref": "#/$defs/portableInteger" },
          "retry_number": { "type": "integer", "minimum": 1 },
          "expected_ceiling_us": { "$ref": "#/$defs/portableInteger" }
        },
        "required": ["initial_delay_us", "cap_us", "retry_number", "expected_ceiling_us"]
      }
    },
    "barrier_cases": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "class": { "enum": ["best-effort", "required"] },
          "outcome": { "enum": ["success", "terminal"] },
          "expected_barrier": { "enum": ["delivered", "required-exhausted"] }
        },
        "required": ["class", "outcome", "expected_barrier"]
      }
    }
  },
  "required": ["format", "event_completion", "projection_cases", "retry_cases", "barrier_cases"],
  "$defs": {
    "material": {
      "type": "string",
      "pattern": "^[0-9a-f]{64}$"
    },
    "timestamp": {
      "type": "string",
      "pattern": "^[0-9]{4}-(0[1-9]|1[0-2])-([0-2][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]\\.[0-9]{6}Z$"
    },
    "portableInteger": {
      "type": "integer",
      "minimum": 0,
      "maximum": 9223372036854775807
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://gantry.invalid/protocol/concurrent-lifecycle/v1/schema.json",
  "title": "Gantry concurrent-lifecycle conformance vectors v1",
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "format": { "const": "gantry.concurrent-lifecycle-vectors/v1" },
    "task_statuses": {
      "type": "array",
      "minItems": 5,
      "maxItems": 5,
      "uniqueItems": true,
      "items": { "type": "string", "minLength": 1 }
    },
    "abort_results": {
      "type": "array",
      "minItems": 3,
      "maxItems": 3,
      "uniqueItems": true,
      "items": { "enum": ["already-settled", "failed", "stopped"] }
    },
    "terminal_categories": {
      "type": "array",
      "minItems": 4,
      "maxItems": 4,
      "uniqueItems": true,
      "items": { "type": "string", "minLength": 1 }
    },
    "event_kinds": {
      "type": "array",
      "minItems": 8,
      "maxItems": 8,
      "uniqueItems": true,
      "items": { "type": "string", "minLength": 1 }
    },
    "cases": {
      "type": "array",
      "minItems": 4,
      "maxItems": 4,
      "uniqueItems": true,
      "items": { "type": "string", "minLength": 1 }
    }
  },
  "required": [
    "format",
    "task_statuses",
    "abort_results",
    "terminal_categories",
    "event_kinds",
    "cases"
  ]
}

{
  "$id": "https://gantry.example/protocol/schemas/embedding-contracts-v1.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "properties": {
    "catalog": { "const": "gantry.embedding-contracts" },
    "major": { "const": 1 },
    "minor": { "const": 0 },
    "specification_revision": {
      "pattern": "^[0-9a-f]{64}$",
      "type": "string"
    },
    "operations": {
      "items": { "$ref": "#/$defs/operation" },
      "minItems": 1,
      "type": "array",
      "uniqueItems": true
    },
    "failure_matrix": {
      "items": { "$ref": "#/$defs/failure" },
      "minItems": 1,
      "type": "array",
      "uniqueItems": true
    },
    "trait_bounds": {
      "items": { "$ref": "#/$defs/traitBound" },
      "minItems": 1,
      "type": "array",
      "uniqueItems": true
    }
  },
  "required": [
    "catalog",
    "major",
    "minor",
    "specification_revision",
    "operations",
    "failure_matrix",
    "trait_bounds"
  ],
  "$defs": {
    "wireName": {
      "pattern": "^[a-z0-9](?:[a-z0-9_-]*[a-z0-9])?$",
      "type": "string"
    },
    "rustName": {
      "pattern": "^[A-Z][A-Za-z0-9]*$",
      "type": "string"
    },
    "requirements": {
      "items": {
        "pattern": "^GNT-[A-Za-z0-9.-]+$",
        "type": "string"
      },
      "minItems": 1,
      "type": "array",
      "uniqueItems": true
    },
    "wireNames": {
      "items": { "$ref": "#/$defs/wireName" },
      "type": "array",
      "uniqueItems": true
    },
    "operation": {
      "additionalProperties": false,
      "properties": {
        "wire": { "$ref": "#/$defs/wireName" },
        "rust": { "$ref": "#/$defs/rustName" },
        "service": {
          "enum": [
            "event",
            "executor",
            "hook",
            "identity",
            "journal",
            "lifecycle",
            "preflight"
          ]
        },
        "role": {
          "enum": [
            "event-sink",
            "executor-adapter",
            "hook-factory",
            "identity-source",
            "integration-preflight",
            "interpreter",
            "journal-storage",
            "operation-hook"
          ]
        },
        "applicable_profiles": {
          "items": {
            "enum": [
              "analyzer",
              "concurrent-evaluator",
              "durable-runtime",
              "embedding",
              "evaluator",
              "frontend"
            ]
          },
          "minItems": 1,
          "type": "array",
          "uniqueItems": true
        },
        "request_fields": { "$ref": "#/$defs/wireNames" },
        "optional_request_fields": { "$ref": "#/$defs/wireNames" },
        "result_variants": {
          "items": { "$ref": "#/$defs/wireName" },
          "minItems": 1,
          "type": "array",
          "uniqueItems": true
        },
        "error_categories": { "$ref": "#/$defs/wireNames" },
        "acceptance": { "$ref": "#/$defs/wireName" },
        "idempotency": { "$ref": "#/$defs/wireName" },
        "cancellation": { "$ref": "#/$defs/wireName" },
        "async_kind": {
          "enum": ["borrowed-future", "owned-task-future", "synchronous"]
        },
        "requirements": { "$ref": "#/$defs/requirements" }
      },
      "required": [
        "wire",
        "rust",
        "service",
        "role",
        "applicable_profiles",
        "request_fields",
        "optional_request_fields",
        "result_variants",
        "error_categories",
        "acceptance",
        "idempotency",
        "cancellation",
        "async_kind",
        "requirements"
      ],
      "type": "object"
    },
    "failure": {
      "additionalProperties": false,
      "properties": {
        "origin": { "$ref": "#/$defs/wireName" },
        "boundary": { "$ref": "#/$defs/wireName" },
        "mapping": { "$ref": "#/$defs/wireName" },
        "poison_scope": { "$ref": "#/$defs/wireName" },
        "requirements": { "$ref": "#/$defs/requirements" }
      },
      "required": [
        "origin",
        "boundary",
        "mapping",
        "poison_scope",
        "requirements"
      ],
      "type": "object"
    },
    "traitBound": {
      "additionalProperties": false,
      "properties": {
        "role": {
          "enum": [
            "event-sink",
            "executor-adapter",
            "hook-factory",
            "identity-source",
            "integration-preflight",
            "journal-storage",
            "operation-hook"
          ]
        },
        "send": { "type": "boolean" },
        "sync": { "type": "boolean" },
        "returned_future": { "enum": ["send-borrowed", "synchronous"] },
        "requirements": { "$ref": "#/$defs/requirements" }
      },
      "required": ["role", "send", "sync", "returned_future", "requirements"],
      "type": "object"
    }
  },
  "title": "Gantry v1 embedding contract catalog",
  "type": "object"
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://gantry.invalid/protocol/package-services/v1/schema.json",
  "title": "Gantry package identity and UTC service values v1",
  "$defs": {
    "fresh_identity_material": {
      "type": "string",
      "pattern": "^[0-9a-f]{64}$"
    },
    "utc_timestamp": {
      "type": "string",
      "pattern": "^[0-9]{4}-(0[1-9]|1[0-2])-([0-2][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]\\.[0-9]{6}Z$"
    }
  },
  "oneOf": [
    { "$ref": "#/$defs/fresh_identity_material" },
    { "$ref": "#/$defs/utc_timestamp" }
  ]
}
